const app=document.getElementById('app');
const liveStatus=document.getElementById('liveStatus');

let surface='learner';
let learner='welcome';
let staff='dashboard';
let requestHeadingFocus=true;
let restoreFocusTestId=null;

let networkOnline=true;
let syncState='synced';
let queuedCount=0;
let mediaState='available';

let goal='';
let editingGoal=false;
let recommendationMode='available';
let draftFields={type:'Multiple choice',domain:'Vocabulary',prompt:'Choose the natural greeting.',answer:'Hello',feedback:'“Hello” is a common greeting.',source:'Internal authoring example'};
let publishedFields={...draftFields};
let draftError='';
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function updateDraft(key,value){draftFields[key]=value;draftSaved=false;if(key==='source')licenseVerified=false}
function finishGoal(){navLearner(editingGoal?'profile':'placementOffer');editingGoal=false}
function submitForReview(){if(!draftFields.prompt.trim()||!draftFields.answer.trim()){draftError='Prompt and correct answer are required.';announce(draftError);render(false);return}draftError='';staff='review';setHeadingFocus();render()}
function setRecommendationMode(mode){recommendationMode=mode;surface='learner';navLearner('home')}
function fallbackHome(){const empty=recommendationMode==='empty';return phone(page(empty?'Nothing eligible right now':'Choose your next step',`<p class="muted">${empty?'There is no eligible work in this demo state. This does not mean you have completed or mastered the course.':'Recommendation is unavailable. Eligible curriculum and due reviews remain available.'}</p><button class="btn primary" onclick="navLearner('${empty?'course':'learn'}')">${empty?'Browse course':'Browse eligible cycles'}</button>`,'L-010',empty?'Content gap':'Curriculum fallback'),'home')}
let placementStep=0;
let placementAnswers={};
let placementSkipped=new Set();
let placementSelected=null;
let placementFeedback=null;

let cycleDomain='vocabulary';
let cycleStep=0;
let selected=null;
let validation='';
let response={first:null,retry:null,retryCount:0,assisted:false,skipped:false,result:null,final:false};
let cycleEvidence=[];
let playCounts={};

let contentDraftRevision=4;
let licenseVerified=false;
let draftSaved=true;
let reviewNote='';
let publishedRevision=3;
let contentPreviewOpen=false;
let lockedPreviewOpen=false;
let publishDialogOpen=false;

const learnerSteps=['intro','review','learn','retrieve','transfer','checkIntro','check','summary'];
const domains={
  vocabulary:{
    label:'Vocabulary',title:'Basic greetings',reason:'Due for review',learnTitle:'How are you?',learnBody:'A common greeting used to ask how someone is doing.',learnExample:'Example: “Hi, Mia. How are you?”',
    review:{prompt:'Which means “hello”?',options:[['Hello','hello'],['Thanks','thanks'],['Goodbye','goodbye']],answer:'hello'},
    retrieve:{prompt:'Choose the best reply: “How are you?”',options:[["I’m good, thanks.",'good'],['Go to school.','go'],['Blue.','blue']],answer:'good',hint:'Think of a short answer about how you feel.'},
    transfer:{prompt:'You meet a classmate in the morning. Which opening fits?',options:[['Good morning!','morning'],['Good night!','night'],['See you yesterday!','yesterday']],answer:'morning'},
    check:{prompt:'Choose the natural reply to “Nice to meet you.”',options:[['Nice to meet you too.','meettoo'],['I am table.','table'],['Yesterday blue.','blue']],answer:'meettoo'}
  },
  grammar:{
    label:'Grammar',title:'Present simple: be',reason:'Build a foundation',learnTitle:'am / is / are',learnBody:'Use “am” with I, “is” with he/she/it, and “are” with you/we/they.',learnExample:'Examples: “I am ready.” “She is a student.” “They are classmates.”',
    review:{prompt:'Which sentence is correct?',options:[['She is a student.','is'],['She are a student.','are'],['She am a student.','am']],answer:'is'},
    retrieve:{prompt:'Complete: “He ___ my friend.”',options:[['is','is'],['are','are'],['am','am']],answer:'is',hint:'He, she and it use “is”.'},
    transfer:{prompt:'Choose the natural sentence about two people.',options:[['They are classmates.','are'],['They is classmates.','is'],['They am classmates.','am']],answer:'are'},
    check:{prompt:'Complete independently: “I ___ ready.”',options:[['am','am'],['is','is'],['are','are']],answer:'am'}
  },
  listening:{
    label:'Listening',title:'Listening: simple greetings',reason:'Needs more evidence',learnTitle:'Listen for the greeting, then respond',learnBody:'Practice audio can be replayed. In an independent Check, Mingo may limit the number of offered plays.',learnExample:'Client playback requests are telemetry only; they do not prove physical listening.',
    review:{prompt:'Play the audio, then choose what you heard.',audio:'Hello',options:[['Hello','hello'],['Goodbye','goodbye'],['Thank you','thanks']],answer:'hello'},
    retrieve:{prompt:'Play the audio, then choose the natural reply.',audio:'How are you?',options:[["I’m good, thanks.",'good'],['Tomorrow blue.','blue'],['At seven table.','table']],answer:'good',hint:'The speaker asks how you are feeling.'},
    transfer:{prompt:'Play the audio. Which reply fits the new context?',audio:'Good morning',options:[['Good morning!','morning'],['Good night!','night'],['Yesterday!','yesterday']],answer:'morning'},
    check:{prompt:'Independent Check: play the audio and choose the natural reply.',audio:'Nice to meet you',options:[['Nice to meet you too.','meettoo'],['I am table.','table'],['Tomorrow blue.','blue']],answer:'meettoo',maxPlays:2}
  }
};
const placementItems=[
  {domain:'Vocabulary',prompt:'Which means “hello”?',options:[['Hello','hello'],['Thanks','thanks'],['Goodbye','goodbye']],answer:'hello'},
  {domain:'Grammar',prompt:'Choose the correct sentence.',options:[['She is here.','is'],['She are here.','are'],['She am here.','am']],answer:'is'},
  {domain:'Listening',prompt:'Play the audio, then choose what you heard.',audio:'Good morning',options:[['Good morning','morning'],['Good night','night'],['Thank you','thanks']],answer:'morning',maxPlays:2,skippable:true}
];

function announce(message){liveStatus.textContent='';setTimeout(()=>{liveStatus.textContent=message||''},0)}
function setHeadingFocus(){requestHeadingFocus=true}
function page(title,body,screenId,eyebrow=''){return `<div data-screen-id="${screenId}">${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1 class="page-title" tabindex="-1">${title}</h1>${body}</div>`}
function statusLabel(){if(!networkOnline)return 'Offline';const map={synced:'Synced',local_queued:'Saved on device',syncing:'Syncing',partial:'Partially synced',failed_retryable:'Sync needs retry',reauth:'Sign-in required',canonical_refresh:'Refresh required'};return map[syncState]||'Online'}
function offlineBanner(){if(!networkOnline)return '<div class="offline-banner" role="status">You’re offline. Downloaded eligible work can continue. Device-saved actions are not server-confirmed.</div>';if(syncState==='local_queued')return '<div class="sync-banner" role="status">Saved actions are still queued until sync receives server acknowledgement.</div>';if(syncState==='syncing')return '<div class="sync-banner" role="status">Syncing saved actions. This is not confirmation yet.</div>';return ''}
function bottom(active){return `<nav class="bottom-nav" aria-label="Learner primary"><button data-testid="nav-home" class="nav-btn ${active==='home'?'active':''}" onclick="navLearner('home')">Home</button><button data-testid="nav-learn" class="nav-btn ${active==='learn'?'active':''}" onclick="navLearner('learn')">Learn</button><button data-testid="nav-course" class="nav-btn ${active==='course'?'active':''}" onclick="navLearner('course')">Course</button><button data-testid="nav-profile" class="nav-btn ${active==='profile'?'active':''}" onclick="navLearner('profile')">Profile</button></nav>`}
function phone(content,active='home',focused=false){return `<div class="learner-stage"><section class="phone"><div class="phone-head"><div class="brand">Mingo</div><div class="sync-dot" data-testid="sync-indicator">${statusLabel()}</div></div>${offlineBanner()}<div class="screen">${content}</div>${focused?'':bottom(active)}</section></div>`}
function navLearner(to){learner=to;selected=null;validation='';setHeadingFocus();render()}
function navStaff(to){staff=to;setHeadingFocus();render()}

// ---------------- Onboarding / placement ----------------
function welcome(){return phone(page('Learn a little. Keep the evidence honest.',`<p class="muted">Mingo starts small: one clear objective, short practice, independent checks, and transparent uncertainty.</p><div class="card soft"><strong>No long gate.</strong><p class="muted">Goal and placement are optional. You can start learning with a provisional state.</p></div><button data-testid="action-L-002-start" class="btn primary full" onclick="navLearner('goal')">Start learning</button>`,'L-002','Welcome'),'home',true)}
function goalScreen(){return phone(page('What are you learning for?',`<p class="muted">Optional. This may shape examples, not measured skill.</p><div class="stack">${goalOption('Build foundations','foundations')}${goalOption('Everyday conversation','conversation')}${goalOption('Study / work basics','study')}</div><div class="actions" style="margin-top:16px"><button data-testid="action-L-003-continue" class="btn primary" onclick="finishGoal()">${editingGoal?'Save goal':'Continue'}</button><button data-testid="action-L-003-skip" class="btn ghost" onclick="goal='';finishGoal()">${editingGoal?'Clear goal':'Skip for now'}</button></div>`,'L-003','Optional goal'),'home',true)}
function goalOption(label,value){return `<button class="option ${goal===value?'selected':''}" aria-pressed="${goal===value?'true':'false'}" onclick="goal='${value}';render(false)">${label}</button>`}
function placementOffer(){return phone(page('Want a short starting check?',`<p>About 3 representative questions in this prototype: Vocabulary, Grammar and Listening.</p><div class="card soft"><strong>Provisional only.</strong><p class="muted">This is not a CEFR certificate. You can skip it and begin with “not enough evidence”.</p></div><div class="actions"><button data-testid="action-L-004-take" class="btn primary" onclick="beginPlacement()">Take placement</button><button data-testid="action-L-004-skip" class="btn secondary" onclick="skipPlacement()">Start without it</button></div>`,'L-004','Placement'),'home',true)}
function beginPlacement(){placementStep=0;placementAnswers={};placementSkipped=new Set();placementSelected=null;placementFeedback=null;learner='placementQuestion';setHeadingFocus();render()}
function skipPlacement(){placementStep=placementItems.length;placementAnswers={};placementSkipped=new Set(['Vocabulary','Grammar','Listening']);learner='placementResult';setHeadingFocus();render()}
function placementQuestion(){const item=placementItems[placementStep];if(!item){learner='placementResult';return placementResult()}const mediaBlocked=Boolean(item.audio&&!networkOnline&&mediaState==='unavailable');const audio=item.audio?audioControl(`placement-${placementStep}`,item.audio,'check',item.maxPlays||2):'';const responseArea=mediaBlocked?'<div class="feedback bad" role="status"><strong>Listening media unavailable.</strong><br>This domain cannot be assessed from text alone. Skip Listening or return when media is available.</div>':`${options(item.options,'placement')} ${placementFeedback?`<div class="feedback ${placementFeedback==='correct'?'good':'bad'}" role="status"><strong>Recorded.</strong><br>This result contributes only to a provisional starting picture.</div>`:''}${validation?`<div class="validation" role="alert">${validation}</div>`:''}`;const body=`<p class="muted">${item.domain} · ${placementStep+1} of ${placementItems.length}</p><p>${item.prompt}</p>${audio}${responseArea}<div class="actions">${mediaBlocked?'':`<button data-testid="action-L-005-submit" class="btn primary" ${placementSelected===null||placementFeedback?'disabled':''} onclick="submitPlacement()">Submit</button>`}${item.skippable?'<button data-testid="action-L-005-skip-domain" class="btn ghost" onclick="skipPlacementDomain()">Skip Listening</button>':''}${placementFeedback?'<button class="btn secondary" onclick="nextPlacement()">Next</button>':''}</div>`;return phone(page('Placement question',body,'L-005','Optional placement'),'home',true)}
function choosePlacement(v){if(placementFeedback)return;placementSelected=v;validation='';render(false)}
function submitPlacement(){const item=placementItems[placementStep];if(placementSelected===null){validation='Choose an answer or use the explicit skip option where available.';announce(validation);render(false);return}placementAnswers[item.domain]={answer:placementSelected,correct:placementSelected===item.answer};placementFeedback=placementSelected===item.answer?'correct':'incorrect';announce('Placement response recorded.');render(false)}
function nextPlacement(){placementStep+=1;placementSelected=null;placementFeedback=null;validation='';playCounts={};if(placementStep>=placementItems.length){learner='placementResult';setHeadingFocus()}render()}
function skipPlacementDomain(){const item=placementItems[placementStep];placementSkipped.add(item.domain);placementAnswers[item.domain]={skipped:true};nextPlacement()}
function placementResult(){const evidence=['Vocabulary','Grammar','Listening'].map(d=>{const a=placementAnswers[d];const text=!a||a.skipped?'Not enough evidence yet':a.correct?'Some starting evidence':'Needs more evidence';return `<div class="metric"><span>${d}</span><strong>${text}</strong></div>`}).join('');return phone(page('Your starting point is provisional',`<p class="muted">Mingo will update this picture as you learn. No certified CEFR score is claimed.</p><div class="card soft">${evidence}</div><button data-testid="action-L-006-home" class="btn primary full" onclick="navLearner('home')">Go to Home</button>`,'L-006','Placement result'),'home',true)}

// ---------------- Main learner shell ----------------
function learnerHome(){if(recommendationMode!=='available')return fallbackHome();return phone(page('Ready for a short cycle?',`<p class="muted">One clear objective. You can stop when the cycle ends.</p><div class="card"><span class="reason">Due for review</span><h2 style="margin-top:10px">Basic greetings</h2><p>Review a few words, use them in context, then do a quick Check.</p><p class="muted">About 5 min</p><button data-testid="action-L-010-start-cycle" class="btn primary full" onclick="startCycle('vocabulary')">Start cycle</button></div><div class="card soft"><div class="metric"><span>Today’s target</span><strong>0 / 1 cycle</strong></div><div class="metric"><span>Streak</span><strong>4 days</strong></div><p class="muted" style="margin-top:12px">Streak shows study activity, not skill level.</p></div>${!networkOnline||syncState!=='synced'?'<div class="notice">Device/network status is shown separately from server-confirmed progress.</div>':''}`,'L-010','Today'),'home')}
function learnHub(){if(recommendationMode==='empty')return fallbackHome();const cards=Object.entries(domains).map(([key,d])=>`<div class="card domain-card"><div><span class="reason">${d.reason}</span><h2 style="margin-top:10px">${d.label}: ${d.title}</h2><p class="muted">Review → Learn → Retrieve → Transfer → Check</p></div><button data-testid="action-L-020-start-${key}" class="btn primary" onclick="startCycle('${key}')">Start</button></div>`).join('');return phone(page('Choose a representative cycle',`${cards}<div class="card soft"><h3>Deterministic fallback</h3><p class="muted">If recommendation/ML is unavailable, Mingo still offers eligible curriculum and due reviews.</p></div>`,'L-020','Learn'),'learn')}
function course(){return phone(page('Your path',`<div class="card"><span class="status published">Current</span><h3 style="margin-top:8px">Basic greetings</h3><p class="muted">Building evidence</p><button class="btn secondary" onclick="startCycle('vocabulary')">Practice</button></div><div class="card"><span class="status review">Due review</span><h3 style="margin-top:8px">Introducing yourself</h3><p class="muted">A quick review is due.</p></div><div class="card soft"><span class="status draft">Locked · preview available</span><h3 style="margin-top:8px">Asking simple questions</h3><p class="muted">Complete the prerequisite first. Preview won’t unlock progress.</p><button data-testid="action-L-042-preview" class="btn ghost" onclick="openLockedPreview()">Preview</button></div><dialog id="lockedPreviewDialog" aria-labelledby="lockedPreviewTitle"><div class="dialog-body"><h2 id="lockedPreviewTitle">Preview: Asking simple questions</h2><p>This preview shows the objective outline only.</p><div class="notice">Preview does not create evidence, progress, completion or unlock. Prerequisite remains required.</div><div class="dialog-actions"><button data-testid="action-L-042-close" class="btn primary" onclick="closeLockedPreview()">Close preview</button></div></div></dialog>`,'L-040','Course'),'course')}
function openLockedPreview(){lockedPreviewOpen=true;restoreFocusTestId='action-L-042-preview';render(false);const d=document.getElementById('lockedPreviewDialog');if(d){d.showModal();d.querySelector('button').focus()}}
function closeLockedPreview(){const d=document.getElementById('lockedPreviewDialog');if(d&&d.open)d.close();lockedPreviewOpen=false;render(false);restoreFocus()}
function profile(){return phone(page('Your learning evidence',`<div class="evidence"><strong>Vocabulary · Building</strong><p class="muted">Recent independent recall is available; Mingo still needs repeated evidence.</p></div><div class="evidence"><strong>Listening · Needs more evidence</strong><p class="muted">Not enough independent Check evidence yet.</p></div><div class="card soft"><div class="metric"><span>Goal</span><strong>${goal||'Not set'}</strong></div><div class="metric"><span>Daily target</span><strong>1 cycle</strong></div></div><div class="actions"><button class="btn secondary" onclick="editingGoal=true;navLearner('goal')">Edit goal</button><button data-testid="action-L-050-sync" class="btn secondary" onclick="navLearner('sync')">Sync status</button></div>`,'L-050','Profile'),'profile')}

// ---------------- Offline / sync state machine ----------------
function sync(){const labels={synced:['All caught up','Server-confirmed state is current.'],local_queued:['Saved on this device',`${queuedCount||1} action(s) are waiting for sync. They are not server-confirmed.`],syncing:['Syncing','Saved actions are being reconciled. Do not treat this as success yet.'],partial:['Some work is still pending','Some commands were acknowledged; others remain queued.'],failed_retryable:['Sync needs retry','A temporary failure occurred. Retry the same durable command identity; do not re-enter duplicate answers.'],reauth:['Sign in again','The local queue is preserved, but permission/session must be refreshed before server acceptance.'],canonical_refresh:['Refresh from server','The server-confirmed state differs from the local view. Refresh canonical state; do not overwrite it locally.']};const pair=labels[syncState]||labels.synced;let action='';if(networkOnline&&syncState==='local_queued')action='<button data-testid="action-L-060-start-sync" class="btn primary" onclick="startSync()">Start sync</button>';if(syncState==='syncing')action='<div class="actions"><button data-testid="action-L-060-ack" class="btn primary" onclick="simulateAck()">Simulate server acknowledgement</button><button class="btn secondary" onclick="simulateSyncFailure()">Simulate failure</button><button class="btn secondary" onclick="simulatePartial()">Simulate partial</button></div>';if(syncState==='failed_retryable')action='<button data-testid="action-L-061-retry" class="btn primary" onclick="startSync()">Retry safely</button>';if(syncState==='partial')action='<button class="btn primary" onclick="startSync()">Sync remaining</button>';if(syncState==='reauth')action='<button class="btn primary" onclick="simulateReauthComplete()">Simulate re-auth complete</button>';if(syncState==='canonical_refresh')action='<button data-testid="action-L-061-refresh" class="btn primary" onclick="simulateCanonicalRefresh()">Refresh canonical state</button>';const controls=`<div class="prototype-test-controls"><strong>Prototype recovery controls</strong><div class="actions"><button class="btn secondary" onclick="simulateSyncFailure()">Retryable failure</button><button class="btn secondary" onclick="simulatePartial()">Partial sync</button><button class="btn secondary" onclick="simulateReauth()">Re-auth</button><button class="btn secondary" onclick="simulateCanonicalMismatch()">Canonical refresh</button></div></div>`;return phone(page(pair[0],`<div class="card"><h3>${statusLabel()}</h3><p class="muted">${pair[1]}</p>${action}</div>${controls}<button class="btn secondary" onclick="navLearner('profile')">Back</button>`,'L-060','Sync status'),'profile')}
function markBusinessAction(){queuedCount+=1;syncState='local_queued';announce('Saved locally. Server acknowledgement is required.')}
function startSync(){if(!networkOnline){announce('Still offline. Sync cannot start.');return}syncState='syncing';announce('Sync started; no server acknowledgement yet.');render(false)}
function simulateAck(){syncState='synced';queuedCount=0;announce('Mock server acknowledgement received. State is now synced.');render(false)}
function simulateSyncFailure(){syncState='failed_retryable';announce('Sync failed temporarily.');render(false)}
function simulatePartial(){syncState='partial';queuedCount=Math.max(1,queuedCount);announce('Partial sync simulated.');render(false)}
function simulateReauth(){syncState='reauth';announce('Re-authentication required.');render(false)}
function simulateReauthComplete(){syncState=queuedCount?'local_queued':'synced';announce('Session refreshed. Pending work is still not acknowledged.');render(false)}
function simulateCanonicalMismatch(){syncState='canonical_refresh';announce('Canonical refresh required.');render(false)}
function simulateCanonicalRefresh(){syncState='synced';queuedCount=0;announce('Canonical server state refreshed.');render(false)}

// ---------------- Learning cycle ----------------
function resetResponse(){selected=null;validation='';response={first:null,retry:null,retryCount:0,assisted:false,skipped:false,result:null,final:false}}
function startCycle(domain='vocabulary'){cycleDomain=domain;cycleStep=0;cycleEvidence=[];playCounts={};resetResponse();learner='cycle';setHeadingFocus();render()}
function currentStep(){return learnerSteps[cycleStep]}
function nextCycle(){cycleStep=Math.min(cycleStep+1,learnerSteps.length-1);resetResponse();setHeadingFocus();render()}
function choose(v){if(response.result&&response.final)return;selected=v;validation='';render(false)}
function useHint(){if(currentStep()==='check'){return}response.assisted=true;validation='';announce('Hint used. Any answer on this item remains assisted.');render(false)}
function skipItem(){const step=currentStep();if(step==='check'){return}response.skipped=true;response.final=true;response.result='skipped';selected=null;validation='';cycleEvidence.push({domain:cycleDomain,step,outcome:'skipped',assisted:response.assisted});markBusinessAction();announce('Skipped for now. No completion or mastery is awarded for this item.');render(false)}
function retryItem(){if(response.retryCount>=1)return;response.retryCount=1;response.result=null;response.final=false;selected=null;validation='';announce('Retry available. The first response is preserved.');render(false)}
function submitStep(step,item,allowRetry=false){if(selected===null){validation='Choose an answer before submitting. Use “Skip for now” only where that explicit action is offered.';announce(validation);render(false);return}const correct=selected===item.answer;if(response.first===null)response.first=selected;else response.retry=selected;response.result=correct?'correct':'incorrect';const canRetry=allowRetry&&!correct&&response.retryCount<1;if(!canRetry)response.final=true;cycleEvidence.push({domain:cycleDomain,step,outcome:correct?'correct':'incorrect',first:response.first,retry:response.retry,assisted:response.assisted,retryCount:response.retryCount});markBusinessAction();announce(correct?(response.assisted?'Correct with assistance recorded.':'Correct response recorded.'):'Incorrect response recorded.');render(false)}
function continueAfterResult(){if(!response.final&&!response.skipped)return;nextCycle()}
function responseControls(step,item,allowHint=false,allowSkip=true,allowRetry=false){const canSubmit=selected!==null&&!response.result;let html=`${options(item.options,'cycle')} ${validation?`<div class="validation" role="alert">${validation}</div>`:''}`;if(!response.result){html+=`<div class="actions"><button data-testid="action-${screenForStep(step)}-submit" class="btn primary" ${canSubmit?'':'disabled'} onclick="submitStep('${step}',domains[cycleDomain]['${step}'],${allowRetry?'true':'false'})">Submit</button>${allowHint?'<button class="btn secondary" onclick="useHint()">Need a hint?</button>':''}${allowSkip?'<button class="btn ghost" onclick="skipItem()">Skip for now</button>':''}</div>`}if(response.assisted)html+=`<p><span class="tag assisted">Assisted</span> <span class="muted small">Hint use stays attached to this response.</span></p>`;if(response.result==='skipped')html+=`<div class="notice" role="status"><strong>Skipped for now.</strong> This creates no completion/mastery claim.<br><button class="btn primary" onclick="continueAfterResult()">Continue</button></div>`;if(response.result==='correct'){html+=`<div class="feedback good" role="status"><strong>${response.assisted?'Correct with a hint.':'Correct.'}</strong><br>${response.assisted?'This remains assisted evidence.':response.retryCount?'Practice retry recorded; the first response remains unchanged.':step==='check'?'Independent Check response recorded in this prototype.':'Practice response recorded in this prototype.'}<br><button class="btn primary" onclick="continueAfterResult()">Continue</button></div>`}if(response.result==='incorrect'){const retry=allowRetry&&response.retryCount<1&&!response.final;html+=`<div class="feedback bad" role="status"><strong>Not quite.</strong><br>${allowRetry?'The first response is preserved.':''}${retry?'<br><button data-testid="action-L-029-retry" class="btn secondary" onclick="retryItem()">Try once more</button>':'<br><span class="small">No more practice retries on this item.</span><br><button class="btn primary" onclick="continueAfterResult()">Continue</button>'}</div>`}return html}
function screenForStep(step){return ({review:'L-022',retrieve:'L-024',transfer:'L-025',check:'L-027'})[step]||'L-020'}
function audioControl(key,text,mode='practice',maxPlays=null){const count=playCounts[key]||0;const limit=mode==='check'?(maxPlays||2):null;const atLimit=limit!==null&&count>=limit;if(!networkOnline&&mediaState==='unavailable'){return `<div class="feedback bad" role="status"><strong>Audio unavailable offline.</strong><br>This required media is not downloaded on this demo device. No assessment completion is fabricated.</div>`}return `<div class="audio-control"><button data-testid="audio-${key}" class="btn secondary" ${atLimit?'disabled':''} onclick="playAudio('${key}','${text.replace(/'/g,"\\'")}','${mode}',${limit===null?'null':limit})">▶ Play audio</button><span class="audio-count">${mode==='check'?`Offered plays: ${count} / ${limit}`:`Playback requests: ${count} · practice replay available`}</span></div><p class="muted small">Playback request count is client telemetry only; it does not prove physical listening or authorize scoring.</p>`}
function playAudio(key,text,mode,limit){const count=playCounts[key]||0;if(limit!==null&&count>=limit){announce('Play limit reached.');return}playCounts[key]=count+1;try{if('speechSynthesis'in window){speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(text);utter.lang='en-US';speechSynthesis.speak(utter)}}catch(e){}announce(`Playback requested. ${mode==='check'?'Assessment play policy applies.':'Practice replay remains available.'}`);render(false)}
function mediaBlockedResponse(isCheck=false){if(!isCheck&&response.skipped)return '<div class="notice" role="status"><strong>Skipped for now.</strong> Missing media practice was skipped. No completion or mastery is awarded.<br><button class="btn primary" onclick="continueAfterResult()">Continue</button></div>';return `<div class="feedback bad" role="status"><strong>Required audio is unavailable offline.</strong><br>${isCheck?'This independent Check cannot be completed without its audio condition. No result is created.':'This practice item cannot use the missing audio in this demo.'}</div><div class="actions">${isCheck?'':'<button class="btn ghost" onclick="skipItem()">Skip for now</button>'}<button class="btn secondary" onclick="navLearner('learn')">Leave cycle</button></div>`}
function cycle(){const step=currentStep();const d=domains[cycleDomain];const pct=((cycleStep+1)/learnerSteps.length)*100;let body=`<div class="progress" style="--progress:${pct}%" aria-label="Cycle progress"><span></span></div><p class="muted">${d.label} · ${cycleStep+1} of ${learnerSteps.length}</p>`;if(step==='intro')body+=`<h2>${d.title}</h2><p>Review what’s due, learn one small idea, retrieve it, use it differently, then do an independent Check.</p><p class="muted">About 5 min · ${d.reason}. Duration is a configurable product hypothesis.</p><button class="btn primary full" onclick="nextCycle()">Begin</button>`;if(step==='review'){const item=d.review;const blocked=Boolean(item.audio&&!networkOnline&&mediaState==='unavailable');body+=`<h2>Review</h2><p>${item.prompt}</p>${item.audio?audioControl('review',item.audio,'practice'):''}${blocked?mediaBlockedResponse(false):responseControls('review',item,false,true,false)}`};if(step==='learn')body+=`<h2>Learn</h2><div class="card soft"><strong>${d.learnTitle}</strong><p class="muted">${d.learnBody}</p><p>${d.learnExample}</p></div>${cycleDomain==='listening'?audioControl('learn','How are you?','practice'):''}<button class="btn primary full" onclick="nextCycle()">Continue</button>`;if(step==='retrieve'){const item=d.retrieve;const blocked=Boolean(item.audio&&!networkOnline&&mediaState==='unavailable');body+=`<h2>Retrieve</h2><p>${item.prompt}</p>${item.audio?audioControl('retrieve',item.audio,'practice'):''}${blocked?mediaBlockedResponse(false):`${response.assisted?`<div class="notice"><strong>Hint:</strong> ${item.hint||'Use the context.'} Any answer after this hint remains assisted.</div>`:''}${responseControls('retrieve',item,true,true,true)}`}`};if(step==='transfer'){const item=d.transfer;const blocked=Boolean(item.audio&&!networkOnline&&mediaState==='unavailable');body+=`<h2>Transfer</h2><p>${item.prompt}</p>${item.audio?audioControl('transfer',item.audio,'practice'):''}${blocked?mediaBlockedResponse(false):responseControls('transfer',item,false,true,false)}`};if(step==='checkIntro')body+=`<h2>Independent Check</h2><p>See what you remember independently. Hints are unavailable before submit.</p>${cycleDomain==='listening'?'<p class="muted">This Listening Check offers at most two playback requests in the current MVP hypothesis.</p>':''}<button class="btn primary full" onclick="nextCycle()">Start Check</button>`;if(step==='check'){const item=d.check;const blocked=Boolean(item.audio&&!networkOnline&&mediaState==='unavailable');body+=`<h2>Check</h2><p>${item.prompt}</p>${item.audio?audioControl('check',item.audio,'check',item.maxPlays||2):''}${blocked?mediaBlockedResponse(true):responseControls('check',item,false,false,false)}`};if(step==='summary'){const assistedCount=cycleEvidence.filter(e=>e.assisted).length;const skippedCount=cycleEvidence.filter(e=>e.outcome==='skipped').length;let syncCopy=syncState==='synced'?'<div class="feedback good">Mock server acknowledgement is current.</div>':syncState==='local_queued'?'<div class="notice"><strong>Saved on this device.</strong> Waiting for server acknowledgement.</div>':syncState==='syncing'?'<div class="notice">Syncing — not confirmed yet.</div>':'<div class="notice">Some work needs sync attention. Open Sync status.</div>';body+=`<h2>Done for now</h2><div class="card"><h3>You practiced</h3><p>${d.label}: review, learn, retrieve, transfer and independent Check.</p><h3>Evidence context</h3><p class="muted">${assistedCount?`${assistedCount} response(s) used assistance. `:''}${skippedCount?`${skippedCount} item(s) were skipped. `:''}Mingo needs repeated evidence before broader claims.</p></div>${syncCopy}<div class="actions"><button class="btn primary" onclick="navLearner('home')">Done for now</button><button class="btn secondary" onclick="startCycle('${cycleDomain}')">Continue learning</button>${syncState!=='synced'?'<button class="btn secondary" onclick="navLearner(\'sync\')">Sync status</button>':''}</div>`}const screenId=({intro:'L-021',review:'L-022',learn:'L-023',retrieve:'L-024',transfer:'L-025',checkIntro:'L-026',check:'L-027',summary:'L-032'})[step];return phone(page(d.title,body,screenId,'Learning cycle'),'learn',true)}
function options(items,scope){return `<div class="stack">${items.map(([label,value])=>`<button class="option ${(scope==='placement'?placementSelected:selected)===value?'selected':''}" aria-pressed="${(scope==='placement'?placementSelected:selected)===value?'true':'false'}" onclick="${scope==='placement'?`choosePlacement('${value}')`:`choose('${value}')`}">${label}</button>`).join('')}</div>`}

// ---------------- Staff ----------------
function staffShell(content,active,screenId){const links=[['dashboard','Dashboard','DB'],['learners','Learners','LR'],['content','Content','CT'],['interventions','Interventions','IN'],['analytics','Analytics','AN'],['admin','Administration','AD']];return `<div class="staff-stage"><aside class="sidebar"><div class="side-brand">Mingo Staff</div>${links.map(x=>`<button class="side-link ${active===x[0]?'active':''}" data-short="${x[2]}" onclick="navStaff('${x[0]}')">${x[1]}</button>`).join('')}</aside><section class="staff-main" data-screen-id="${screenId}">${content}</section></div>`}
function staffPage(title,body,eyebrow=''){return `${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1 class="page-title" tabindex="-1">${title}</h1>${body}`}
function staffDashboard(){return staffShell(staffPage('Dashboard',`<p class="muted">Operational shell with mock data only.</p><div class="staff-grid"><div class="card"><h3>Content awaiting review</h3><strong style="font-size:28px">3</strong></div><div class="card"><h3>Learner support items</h3><strong style="font-size:28px">2</strong></div><div class="card"><h3>System note</h3><p class="muted">No production risk/analytics values are fabricated in this prototype.</p></div></div>`,'Staff'),'dashboard','S-010')}
function learners(){return staffShell(staffPage('Learners',`<div class="table-wrap"><table class="table"><thead><tr><th>Learner</th><th>Learning evidence</th><th>Recent activity</th><th></th></tr></thead><tbody><tr><td>Demo learner A</td><td>Vocabulary · Building</td><td>Cycle today</td><td><button class="btn secondary" onclick="staff='learnerDetail';setHeadingFocus();render()">Open</button></td></tr><tr><td>Demo learner B</td><td>Needs more evidence</td><td>2 days ago</td><td><button class="btn secondary" onclick="staff='learnerDetail';setHeadingFocus();render()">Open</button></td></tr></tbody></table></div>`,'Learners'),'learners','S-020')}
function learnerDetail(){return staffShell(staffPage('Demo learner A',`<button class="btn ghost" onclick="navStaff('learners')">← Learners</button><div class="staff-grid"><div class="card"><h3>Learning evidence</h3><p>Vocabulary · Building</p><p class="muted">No precise mastery percentage is shown.</p></div><div class="card"><h3>Engagement</h3><p>4-day streak</p><p class="muted">Engagement is not mastery.</p></div><div class="card"><h3>Uncertainty</h3><p>More listening evidence needed.</p></div></div><div class="notice">Support views require server-side assigned-learner authorization in Phase 3+. This prototype does not implement permissions.</div>`),'learners','S-021')}
function content(){return staffShell(staffPage('Content library',`<div class="actions" style="margin-bottom:16px"><button class="btn primary" onclick="openEditor()">Create draft</button><button class="btn secondary" onclick="staff='review';setHeadingFocus();render()">Review queue</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Item</th><th>Status</th><th>Revision</th><th></th></tr></thead><tbody><tr><td>Basic greetings</td><td><span class="status draft">Draft</span></td><td>Draft ${contentDraftRevision}</td><td><button class="btn secondary" onclick="openEditor()">Edit</button></td></tr><tr><td>Introductions</td><td><span class="status published">Published</span></td><td>Revision ${publishedRevision}</td><td><button class="btn secondary" onclick="staff='published';setHeadingFocus();render()">View</button></td></tr></tbody></table></div>`,'Content'),'content','S-030')}
function openEditor(){staff='editor';setHeadingFocus();render()}
function editor(){return staffShell(staffPage(`Basic greetings · Draft ${contentDraftRevision}`,`<button class="btn ghost" onclick="navStaff('content')">← Content</button><div class="field"><label for="content-type">Item type</label><select id="content-type" data-testid="field-S-031-type" onchange="updateDraft('type',this.value)">${['Multiple choice','Listening multiple choice'].map(v=>`<option ${draftFields.type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="content-domain">Domain</label><select id="content-domain" data-testid="field-S-031-domain" onchange="updateDraft('domain',this.value)">${['Vocabulary','Grammar','Listening'].map(v=>`<option ${draftFields.domain===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="content-prompt">Prompt</label><textarea id="content-prompt" data-testid="field-S-031-prompt" aria-describedby="prompt-help" oninput="updateDraft('prompt',this.value)">${escapeHtml(draftFields.prompt)}</textarea><span id="prompt-help" class="field-help">Required. Learner-facing prompt for this draft revision.</span></div><div class="field"><label for="content-answer">Correct answer</label><input id="content-answer" data-testid="field-S-031-answer" oninput="updateDraft('answer',this.value)" value="${escapeHtml(draftFields.answer)}" /></div><div class="field"><label for="content-feedback">Feedback</label><textarea id="content-feedback" oninput="updateDraft('feedback',this.value)">${escapeHtml(draftFields.feedback)}</textarea></div><div class="field"><label for="content-source">Source / license</label><input id="content-source" data-testid="field-S-031-source" aria-describedby="source-help" oninput="updateDraft('source',this.value)" value="${escapeHtml(draftFields.source)}" /><span id="source-help" class="field-help">Publication is blocked until provenance/license review passes.</span></div>${draftError?`<div class="validation" role="alert">${draftError}</div>`:''}${reviewNote?`<div class="validation" role="status"><strong>Reviewer note:</strong> ${reviewNote}</div>`:''}<div class="notice">Published revisions can’t be edited. This is a draft.</div><div class="actions" style="margin-top:16px"><button class="btn secondary" onclick="saveDraft()">Save draft</button><button data-testid="action-S-031-preview" class="btn secondary" onclick="staff='contentPreview';setHeadingFocus();render()">Preview</button><button class="btn primary" onclick="submitForReview()">Submit for review</button></div>`,'Draft'),'content','S-031')}
function saveDraft(){if(!draftFields.prompt.trim()||!draftFields.answer.trim()){draftError='Prompt and correct answer are required.';announce(draftError);render(false);return}draftError='';draftSaved=true;reviewNote='';announce('Draft saved locally in the prototype.');render(false)}
function contentPreview(){return staffShell(staffPage(`Preview · Draft ${contentDraftRevision}`,`<button class="btn ghost" onclick="staff='editor';setHeadingFocus();render()">← Editor</button><div class="card"><span class="reason">Learner preview</span><h2 style="margin-top:10px">${escapeHtml(draftFields.prompt)}</h2><div class="stack"><div class="option">${escapeHtml(draftFields.answer)}</div><div class="option">Goodbye</div><div class="option">Tomorrow blue</div></div></div><div class="notice">Preview does not publish, create learner progress or mutate the draft.</div>`,'Content preview'),'content','S-032')}
function sourceLicense(){return staffShell(staffPage('Source & license',`<button class="btn ghost" onclick="staff='review';setHeadingFocus();render()">← Review</button><div class="field"><label for="source-url">Source reference</label><input id="source-url" oninput="updateDraft('source',this.value)" value="${escapeHtml(draftFields.source)}" /></div><div class="field"><label for="license-status">Reuse permission</label><select id="license-status"><option ${licenseVerified?'':'selected'}>Needs confirmation</option><option ${licenseVerified?'selected':''}>Verified for prototype</option></select></div><div class="notice">“Publicly accessible” is not treated as permission to reuse.</div><button data-testid="action-S-033-verify" class="btn primary" onclick="verifyLicense()">Mark verified for prototype</button>`,'Provenance gate'),'content','S-033')}
function verifyLicense(){if(!draftFields.source.trim()){announce('Source reference is required before verification.');return}licenseVerified=true;announce('License/provenance marked verified in prototype.');staff='review';setHeadingFocus();render()}
function review(){return staffShell(staffPage('Content review',`<button class="btn ghost" onclick="navStaff('content')">← Content</button><div class="card"><h3>Basic greetings · Draft ${contentDraftRevision}</h3><p>Editorial checks complete.</p><p><strong>License:</strong> <span class="status ${licenseVerified?'published':'review'}">${licenseVerified?'Verified':'Needs confirmation'}</span></p><p class="muted">Publish remains blocked until provenance/license requirements pass.</p><div class="actions"><button class="btn secondary" onclick="requestChanges()">Request changes</button><button class="btn secondary" onclick="staff='sourceLicense';setHeadingFocus();render()">Open source & license</button><button data-testid="action-S-035-approve" class="btn primary" ${licenseVerified?'':'disabled'} onclick="openPublishDialog()">Approve</button></div></div><dialog id="publishDialog" aria-labelledby="publishDialogTitle"><div class="dialog-body"><h2 id="publishDialogTitle">Publish Revision ${contentDraftRevision}?</h2><p>Publishing creates an immutable revision. Later edits must create a new draft.</p><div class="dialog-actions"><button class="btn secondary" onclick="closePublishDialog()">Cancel</button><button data-testid="action-S-036-confirm" class="btn primary" onclick="confirmPublish()">Confirm publish</button></div></div></dialog>`,'Review queue'),'content','S-035')}
function requestChanges(){reviewNote='Confirm source/license and reviewer notes before resubmitting.';staff='editor';setHeadingFocus();render()}
function openPublishDialog(){if(!licenseVerified)return;publishDialogOpen=true;restoreFocusTestId='action-S-035-approve';render(false);const d=document.getElementById('publishDialog');if(d){d.showModal();d.querySelector('[data-testid="action-S-036-confirm"]').focus()}}
function closePublishDialog(){const d=document.getElementById('publishDialog');if(d&&d.open)d.close();publishDialogOpen=false;render(false);restoreFocus()}
function confirmPublish(){if(!licenseVerified)return;publishedFields={...draftFields};publishedRevision=contentDraftRevision;publishDialogOpen=false;staff='published';setHeadingFocus();announce(`Revision ${publishedRevision} published as immutable in the prototype.`);render()}
function published(){return staffShell(staffPage(`Basic greetings · Revision ${publishedRevision}`,`<button class="btn ghost" onclick="navStaff('content')">← Content</button><div class="feedback good"><strong>Immutable published revision</strong><br>Historical attempts stay pinned to the revision they used.</div><p>Editing this published revision directly is not available.</p><div class="card"><h2>${escapeHtml(publishedFields.prompt)}</h2><p>${escapeHtml(publishedFields.answer)}</p></div><button data-testid="action-S-037-new-draft" class="btn primary" onclick="newDraftFromPublished()">Create new draft from revision</button>`,'Published'),'content','S-037')}
function newDraftFromPublished(){draftFields={...publishedFields};draftError='';contentDraftRevision=publishedRevision+1;licenseVerified=true;reviewNote='';staff='editor';setHeadingFocus();announce(`Draft ${contentDraftRevision} created from published Revision ${publishedRevision}.`);render()}
function placeholder(title,active,copy,screenId){return staffShell(staffPage(title,`<div class="placeholder">${copy}<br><br>This Phase 2 prototype defines navigation/states only. Domain implementation belongs to later phases.</div>`,'Future-ready IA'),active,screenId)}
function staffView(){if(staff==='dashboard')return staffDashboard();if(staff==='learners')return learners();if(staff==='learnerDetail')return learnerDetail();if(staff==='content')return content();if(staff==='editor')return editor();if(staff==='contentPreview')return contentPreview();if(staff==='sourceLicense')return sourceLicense();if(staff==='review')return review();if(staff==='published')return published();if(staff==='interventions')return placeholder('Interventions','interventions','Decision → Exposure → Execution → Outcome stay distinct.','S-040');if(staff==='analytics')return placeholder('Analytics','analytics','Metrics disclose definition, time window and source context.','S-050');if(staff==='admin')return placeholder('Administration','admin','Roles, permissions and audit require server-side authorization.','S-060');return staffDashboard()}

function learnerView(){if(learner==='welcome')return welcome();if(learner==='goal')return goalScreen();if(learner==='placementOffer')return placementOffer();if(learner==='placementQuestion')return placementQuestion();if(learner==='placementResult')return placementResult();if(learner==='home')return learnerHome();if(learner==='learn')return learnHub();if(learner==='course')return course();if(learner==='profile')return profile();if(learner==='sync')return sync();if(learner==='cycle')return cycle();return learnerHome()}
function restoreFocus(){if(!restoreFocusTestId)return;const id=restoreFocusTestId;restoreFocusTestId=null;setTimeout(()=>{const el=document.querySelector(`[data-testid="${id}"]`);if(el)el.focus()},0)}
document.addEventListener('keydown',event=>{
  if(event.key!=='Tab')return;
  const dialog=app.querySelector('dialog[open]');
  if(!dialog)return;
  const controls=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')];
  const first=controls[0],last=controls[controls.length-1];
  if(!first)return;
  if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last.focus()}
  else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first.focus()}
});
function render(focusHeading=requestHeadingFocus){const active=document.activeElement;const focusKey=active?.getAttribute('data-focus-key');app.innerHTML=surface==='learner'?learnerView():staffView();app.querySelectorAll('button,input,select,textarea').forEach((el,i)=>el.setAttribute('data-focus-key',el.getAttribute('data-testid')||el.id||((el.getAttribute('onclick')||'')+'|'+el.textContent.trim())));if(!focusHeading&&focusKey){const match=[...app.querySelectorAll('[data-focus-key]')].find(el=>el.getAttribute('data-focus-key')===focusKey);if(match&&!match.disabled)match.focus();else{const result=app.querySelector('.feedback button,.notice button');if(result)result.focus()}}for(const [id,close] of [['lockedPreviewDialog',closeLockedPreview],['publishDialog',closePublishDialog]]){const dialog=document.getElementById(id);if(dialog)dialog.addEventListener('cancel',event=>{event.preventDefault();close()})}document.getElementById('surfaceLearner').classList.toggle('active',surface==='learner');document.getElementById('surfaceStaff').classList.toggle('active',surface==='staff');document.getElementById('toggleOffline').setAttribute('aria-pressed',networkOnline?'false':'true');document.getElementById('toggleOffline').classList.toggle('active',!networkOnline);if(focusHeading){const h=app.querySelector('.page-title');if(h)h.focus();requestHeadingFocus=false}if(lockedPreviewOpen){const d=document.getElementById('lockedPreviewDialog');if(d&&!d.open)d.showModal()}if(publishDialogOpen){const d=document.getElementById('publishDialog');if(d&&!d.open)d.showModal()}}

function toggleOffline(){networkOnline=!networkOnline;if(!networkOnline){mediaState='unavailable';announce('Offline simulation enabled.')}else{mediaState='available';announce(syncState==='local_queued'?'Connection restored. Queued work is still waiting for server acknowledgement.':'Connection restored.')}render(false)}
function resetFirstUse(){surface='learner';learner='welcome';goal='';placementStep=0;placementAnswers={};placementSkipped=new Set();placementSelected=null;placementFeedback=null;setHeadingFocus();render()}

document.getElementById('surfaceLearner').onclick=()=>{surface='learner';setHeadingFocus();render()};
document.getElementById('surfaceStaff').onclick=()=>{surface='staff';setHeadingFocus();render()};
document.getElementById('toggleOffline').onclick=toggleOffline;
document.getElementById('resetFirstUse').onclick=resetFirstUse;

window.__MINGO_TEST__={
 getState:()=>({surface,learner,staff,networkOnline,syncState,queuedCount,cycleDomain,cycleStep,selected,response:{...response},goal,placementStep,licenseVerified,contentDraftRevision,publishedRevision}),
 actions:{navLearner,navStaff,startCycle,choose,submitStep,useHint,skipItem,retryItem,nextCycle,toggleOffline,startSync,simulateAck,simulateSyncFailure,simulatePartial,simulateReauth,simulateCanonicalMismatch,verifyLicense,confirmPublish,resetFirstUse}
};
render();
